function safeText(value) { return String(value === undefined || value === null ? '' : value).trim(); }
function num(value, fallback) { const n = Number(value); return Number.isFinite(n) ? n : fallback; }
function berlinNow() {
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false });
  const p = {}; for (const part of f.formatToParts(new Date())) { if (part.type !== 'literal') p[part.type] = part.value; }
  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}`;
}
function httpError(item) {
  const j = item && item.json ? item.json : {};
  const container = j.error || (j.body && j.body.error) || (j.response && j.response.body && j.response.body.error);
  if (!container) return '';
  function pick(o) {
    if (!o) return '';
    if (typeof o === 'string') return o.trim();
    if (o.message) return String(o.message).trim();
    if (o.description) return String(o.description).trim();
    if (o.error) return pick(o.error);
    if (o.code) return String(o.code).trim();
    return '';
  }
  const msg = pick(container) || (typeof j.message === 'string' ? j.message.trim() : '');
  if (msg) return msg;
  try { const s = JSON.stringify(container); if (s && s !== '{}') return s.slice(0, 300); } catch (e) {}
  return 'Microsoft Graph request failed';
}

const input = items[0].json || {};
function normDt(v){ const t=safeText(v); if(!t) return ''; return t.replace(/Z$/,'').slice(0,19); }
let start = normDt(input.startDateTime);
let end = normDt(input.endDateTime);
if (!start || !end) {
  const day = berlinNow().slice(0,10);
  start = start || (day + 'T00:00:00');
  end = end || (day + 'T23:59:59');
}
const enc = s => encodeURIComponent(s);
return [{ json: { start, end, url: 'https://graph.microsoft.com/v1.0/me/calendarView?startDateTime=' + enc(start) + '&endDateTime=' + enc(end) + '&$select=subject,start,end,location,organizer,attendees,isAllDay&$orderby=start/dateTime&$top=50' } }];

