if (err) { return [{ json: { status: 'failed', response: 'Tool failed: Yes\n' + 'Tool used: WF_SEARCH_CALENDAR_EVENTS\n' + 'Error message: ' + (err) + '\n' + 'Action taken: None\n' + 'Verification status: Failed', verificationStatus: 'Failed' } }]; }
